			function onBtnDeleteClick(e) {
			    var btnDelete = e.control;
			    
			    util.DataSet.setValue(app, "dsList", 0, "TYPE", "DELETE");
			    util.Msg.confirm(app, "CRM-M002", null, function() {
			        util.DataMap.setValue(app, "dmSave", "INO_DOC_ESNTAL_NO", util.DataMap.getValue(app, "dmDocDtl", "INO_DOC_ESNTAL_NO"));
			        util.Submit.send(app, "subDelete", function(pbSuccess) {
			            
			            if (pbSuccess) {
			                var hostApp = app.getHostAppInstance();
			                
			                if (hostApp.hasAppMethod("doList")) {
			                    hostApp.callAppMethod("doList", "save");
			                    app.lookup("dmSave").clear();
			                    util.Control.redraw(app, "grpData");
			                }
			                
			                if (hostApp.hasAppMethod("selectMdiItem")) {
			                    hostApp.callAppMethod("selectMdiItem", 1);
			                }
			                
			            }
			        });
			    });
			}

